#include <vector>
#include <string>
#include <climits>

using namespace std;

class Solution {
public:
    int palindromePartition(string s, int k) {
        int n = s.size();
        vector<vector<int>> cost(n, vector<int>(n, 0));

        for (int l = 1; l < n; ++l)
            for (int i = 0; i + l < n; ++i)
                cost[i][i + l] = cost[i + 1][i + l - 1] + (s[i] != s[i + l]);

        vector<vector<int>> dp(k + 1, vector<int>(n + 1, INT_MAX));
        dp[0][0] = 0;

        for (int i = 1; i <= k; ++i)
            for (int j = 1; j <= n; ++j)
                for (int m = 0; m < j; ++m)
                    if (dp[i - 1][m] != INT_MAX)
                        dp[i][j] = min(dp[i][j], dp[i - 1][m] + cost[m][j - 1]);

        return dp[k][n];
    }
};
